import { yupResolver } from "@hookform/resolvers/yup";
import { LoadingButton } from "@mui/lab";
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  Radio,
  RadioGroup,
  TextField,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import UploadIcon from "@mui/icons-material/Upload";
import "react-quill/dist/quill.snow.css";
import CustomFileUploads from "src/views/common/CustomFileUploads";

const validationSchema = yup.object().shape({
  // images: yup
  //   .array()
  //   .min(1, "Image is Required")
  //   // .max(5, "You can't upload more than 5 image")
  //   .required("Image is Required"),
  // // .of(
  // //   yup.mixed().test("fileSize", "File size is too large", (value) => {
  // //     if (typeof value === "string") return true;
  // //     return !value || value.size <= 1024 * 1024 * 3; // 5MB
  // //   })
  // // ),
});

const DialogOverviewImages = (props) => {
  const { mode, open, toggle, dataToEdit, onSuccess, itSolutionId } = props;

  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");

  const {
    control,
    handleSubmit,
    reset,

    formState: { errors },
  } = useForm({
    defaultValues: {
      images: [],
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });

  useEffect(() => {
    if (open) {
      setLoading(false);
      setDialogTitle(mode === "add" ? "Add Image" : "Edit Image");
      // reset({
      //   images: dataToEdit?.image_url || null,
      // });
      reset({
        images: dataToEdit?.image_url ? [dataToEdit.image_url] : [],
      });
    }
  }, [dataToEdit, mode, open, reset]);

  console.log("dataToEdit", dataToEdit);

  const onSubmit = (data) => {
    const payload = new FormData();
    if (Array.isArray(data.images)) {
      data.images.forEach((file) => {
        payload.append("images", file);
      });
    } else if (data.images) {
      payload.append("images", data.images);
    }
    // payload.append("images", data.images);
    payload.append("sub_it_solution_list_id", itSolutionId);

    setLoading(true);
    console.log("images", data.images);

    let apiInstance = null;

    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.ITSolutionOverviewImages.edit(dataToEdit.id),
        payload,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );
    } else {
      apiInstance = axiosInstance.post(
        ApiEndPoints.ITSolutionOverviewImages.create,
        payload,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );
    }

    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  return (
    <>
      <Dialog
        open={open}
        onClose={toggle}
        fullWidth
        maxWidth="sm"
        scroll="paper"
      >
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>{dialogTitle}</Box>
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="image-form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={4}>
              <Grid item xs={12}>
                <FormControl fullWidth>
                  <FormLabel htmlFor="images">Image</FormLabel>
                  <Controller
                    name="images"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <CustomFileUploads
                        multiple={true}
                        minHeight="0px"
                        subtitle="(Max file size 3mb)"
                        files={value}
                        onChange={onChange}
                        title={"Add Image"}

                        // MediaUrl={MEDIA_URL}
                      />
                    )}
                  />
                  {errors?.images && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors?.images?.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="image-form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogOverviewImages;
